<!DOCTYPE html>
<html>
<head>
    <title>Verify Your Email</title>
    <meta charset="UTF-8">
    <style>
        body {
            margin: 0;
            padding: 0;
            background-color: #F7F1DE;
            font-family: 'Segoe UI', Tahoma, sans-serif;
        }

        .email-container {
            max-width: 600px;
            margin: 40px auto;
            background-color: #FDFBF6;
            border: 1px solid #EFE4C3;
            border-radius: 12px;
            padding: 40px;
            box-shadow: 0 8px 20px rgba(57, 36, 20, 0.08);
        }

        .logo {
            text-align: center;
            margin-bottom: 30px;
        }

        .logo img {
            width: 120px;
            border-radius: 8px;
        }

        h1 {
            font-family: Georgia, 'Times New Roman', serif;
            font-size: 24px;
            color: #1E0D06;
            margin-bottom: 16px;
            text-align: center;
        }

        p {
            font-size: 16px;
            color: #632F19;
            line-height: 1.6;
            margin-bottom: 20px;
            text-align: center;
        }

        .btn {
            display: block;
            width: fit-content;
            margin: 0 auto;
            background-color: #9D6638;
            color: #FDFBF6;
            text-decoration: none;
            padding: 14px 28px;
            border-radius: 8px;
            font-size: 16px;
            font-weight: 600;
        }

        .alt-link {
            margin-top: 30px;
            text-align: center;
            font-size: 14px;
            color: #7A4327;
        }

        .alt-link a {
            color: #85552F;
            word-break: break-all;
        }

        .footer {
            margin-top: 40px;
            text-align: center;
            font-size: 12px;
            color: #A0843D;
        }
    </style>
</head>
